import 'versiculos_diarios.dart';

/// Versículos del día, en el orden de rotación (un día por entrada).
const List<VersiculoDiario> versiculosDiarios = <VersiculoDiario>[
  VersiculoDiario(24, 29, 11, 11, TemaVersiculo.esperanza, 'Porque yo sé los pensamientos que tengo acerca de vosotros, dice Jehová, pensamientos de paz, y no de mal, para daros el fin que esperáis.'),
  VersiculoDiario(20, 3, 5, 6, TemaVersiculo.fe, 'Fíate de Jehová de todo tu corazón, Y no te apoyes en tu propia prudencia. Reconócelo en todos tus caminos, Y él enderezará tus veredas.'),
  VersiculoDiario(19, 51, 10, 10, TemaVersiculo.pureza, 'Crea en mí, oh Dios, un corazón limpio, Y renueva un espíritu recto dentro de mí.'),
  VersiculoDiario(43, 3, 16, 16, TemaVersiculo.amor, 'Porque de tal manera amó Dios al mundo, que ha dado a su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna.'),
  VersiculoDiario(19, 119, 105, 105, TemaVersiculo.palabra, 'Lámpara es a mis pies tu palabra, Y lumbrera a mi camino.'),
  VersiculoDiario(50, 4, 6, 7, TemaVersiculo.oracion, 'Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias. Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.'),
  VersiculoDiario(62, 1, 9, 9, TemaVersiculo.perdon, 'Si confesamos nuestros pecados, él es fiel y justo para perdonar nuestros pecados, y limpiarnos de toda maldad.'),
  VersiculoDiario(46, 10, 13, 13, TemaVersiculo.tentacion, 'No os ha sobrevenido ninguna tentación que no sea humana; pero fiel es Dios, que no os dejará ser tentados más de lo que podéis resistir, sino que dará también juntamente con la tentación la salida, para que podáis soportar.'),
  VersiculoDiario(50, 4, 13, 13, TemaVersiculo.fortaleza, 'Todo lo puedo en Cristo que me fortalece.'),
  VersiculoDiario(16, 8, 10, 10, TemaVersiculo.gozo, 'Luego les dijo: Id, comed grosuras, y bebed vino dulce, y enviad porciones a los que no tienen nada preparado; porque día santo es a nuestro Señor; no os entristezcáis, porque el gozo de Jehová es vuestra fuerza.'),
  VersiculoDiario(45, 8, 37, 37, TemaVersiculo.victoria, 'Antes, en todas estas cosas somos más que vencedores por medio de aquel que nos amó.'),
  VersiculoDiario(43, 14, 27, 27, TemaVersiculo.paz, 'La paz os dejo, mi paz os doy; yo no os la doy como el mundo la da. No se turbe vuestro corazón, ni tenga miedo.'),
  VersiculoDiario(47, 5, 17, 17, TemaVersiculo.identidad, 'De modo que si alguno está en Cristo, nueva criatura es; las cosas viejas pasaron; he aquí todas son hechas nuevas.'),
  VersiculoDiario(49, 2, 8, 9, TemaVersiculo.gracia, 'Porque por gracia sois salvos por medio de la fe; y esto no de vosotros, pues es don de Dios; no por obras, para que nadie se gloríe.'),
  VersiculoDiario(23, 26, 3, 3, TemaVersiculo.paz, 'Tú guardarás en completa paz a aquel cuyo pensamiento en ti persevera; porque en ti ha confiado.'),
  VersiculoDiario(23, 1, 18, 18, TemaVersiculo.perdon, 'Venid luego, dice Jehová, y estemos a cuenta: si vuestros pecados fueren como la grana, como la nieve serán emblanquecidos; si fueren rojos como el carmesí, vendrán a ser como blanca lana.'),
  VersiculoDiario(48, 2, 20, 20, TemaVersiculo.identidad, 'Con Cristo estoy juntamente crucificado, y ya no vivo yo, mas vive Cristo en mí; y lo que ahora vivo en la carne, lo vivo en la fe del Hijo de Dios, el cual me amó y se entregó a sí mismo por mí.'),
  VersiculoDiario(40, 5, 8, 8, TemaVersiculo.pureza, 'Bienaventurados los de limpio corazón, porque ellos verán a Dios.'),
  VersiculoDiario(59, 4, 7, 7, TemaVersiculo.tentacion, 'Someteos, pues, a Dios; resistid al diablo, y huirá de vosotros.'),
  VersiculoDiario(55, 3, 16, 17, TemaVersiculo.palabra, 'Toda la Escritura es inspirada por Dios, y útil para enseñar, para redargüir, para corregir, para instruir en justicia, a fin de que el hombre de Dios sea perfecto, enteramente preparado para toda buena obra.'),
  VersiculoDiario(19, 16, 11, 11, TemaVersiculo.gozo, 'Me mostrarás la senda de la vida; En tu presencia hay plenitud de gozo; Delicias a tu diestra para siempre.'),
  VersiculoDiario(46, 15, 57, 57, TemaVersiculo.victoria, 'Mas gracias sean dadas a Dios, que nos da la victoria por medio de nuestro Señor Jesucristo.'),
  VersiculoDiario(24, 33, 3, 3, TemaVersiculo.oracion, 'Clama a mí, y yo te responderé, y te enseñaré cosas grandes y ocultas que tú no conoces.'),
  VersiculoDiario(45, 5, 8, 8, TemaVersiculo.amor, 'Mas Dios muestra su amor para con nosotros, en que siendo aún pecadores, Cristo murió por nosotros.'),
  VersiculoDiario(47, 12, 9, 9, TemaVersiculo.gracia, 'Y me ha dicho: Bástate mi gracia; porque mi poder se perfecciona en la debilidad. Por tanto, de buena gana me gloriaré más bien en mis debilidades, para que repose sobre mí el poder de Cristo.'),
  VersiculoDiario(58, 11, 1, 1, TemaVersiculo.fe, 'Es, pues, la fe la certeza de lo que se espera, la convicción de lo que no se ve.'),
  VersiculoDiario(45, 15, 13, 13, TemaVersiculo.esperanza, 'Y el Dios de esperanza os llene de todo gozo y paz en el creer, para que abundéis en esperanza por el poder del Espíritu Santo.'),
  VersiculoDiario(23, 41, 10, 10, TemaVersiculo.fortaleza, 'No temas, porque yo estoy contigo; no desmayes, porque yo soy tu Dios que te esfuerzo; siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia.'),
  VersiculoDiario(45, 8, 38, 39, TemaVersiculo.amor, 'Por lo cual estoy seguro de que ni la muerte, ni la vida, ni ángeles, ni principados, ni potestades, ni lo presente, ni lo por venir, ni lo alto, ni lo profundo, ni ninguna otra cosa creada nos podrá separar del amor de Dios, que es en Cristo Jesús Señor nuestro.'),
  VersiculoDiario(6, 1, 9, 9, TemaVersiculo.fortaleza, 'Mira que te mando que te esfuerces y seas valiente; no temas ni desmayes, porque Jehová tu Dios estará contigo en dondequiera que vayas.'),
  VersiculoDiario(58, 11, 6, 6, TemaVersiculo.fe, 'Pero sin fe es imposible agradar a Dios; porque es necesario que el que se acerca a Dios crea que le hay, y que es galardonador de los que le buscan.'),
  VersiculoDiario(19, 119, 9, 9, TemaVersiculo.pureza, '¿Con qué limpiará el joven su camino? Con guardar tu palabra.'),
  VersiculoDiario(19, 103, 12, 12, TemaVersiculo.perdon, 'Cuanto está lejos el oriente del occidente, Hizo alejar de nosotros nuestras rebeliones.'),
  VersiculoDiario(19, 118, 24, 24, TemaVersiculo.gozo, 'Este es el día que hizo Jehová; Nos gozaremos y alegraremos en él.'),
  VersiculoDiario(25, 3, 22, 23, TemaVersiculo.esperanza, 'Por la misericordia de Jehová no hemos sido consumidos, porque nunca decayeron sus misericordias. Nuevas son cada mañana; grande es tu fidelidad.'),
  VersiculoDiario(62, 5, 4, 4, TemaVersiculo.victoria, 'Porque todo lo que es nacido de Dios vence al mundo; y esta es la victoria que ha vencido al mundo, nuestra fe.'),
  VersiculoDiario(56, 2, 11, 12, TemaVersiculo.gracia, 'Porque la gracia de Dios se ha manifestado para salvación a todos los hombres, enseñándonos que, renunciando a la impiedad y a los deseos mundanos, vivamos en este siglo sobria, justa y piadosamente,'),
  VersiculoDiario(43, 16, 33, 33, TemaVersiculo.paz, 'Estas cosas os he hablado para que en mí tengáis paz. En el mundo tendréis aflicción; pero confiad, yo he vencido al mundo.'),
  VersiculoDiario(40, 26, 41, 41, TemaVersiculo.tentacion, 'Velad y orad, para que no entréis en tentación; el espíritu a la verdad está dispuesto, pero la carne es débil.'),
  VersiculoDiario(58, 4, 12, 12, TemaVersiculo.palabra, 'Porque la palabra de Dios es viva y eficaz, y más cortante que toda espada de dos filos; y penetra hasta partir el alma y el espíritu, las coyunturas y los tuétanos, y discierne los pensamientos y las intenciones del corazón.'),
  VersiculoDiario(43, 1, 12, 12, TemaVersiculo.identidad, 'Mas a todos los que le recibieron, a los que creen en su nombre, les dio potestad de ser hechos hijos de Dios;'),
  VersiculoDiario(40, 7, 7, 7, TemaVersiculo.oracion, 'Pedid, y se os dará; buscad, y hallaréis; llamad, y se os abrirá.'),
  VersiculoDiario(23, 40, 8, 8, TemaVersiculo.palabra, 'Sécase la hierba, marchítase la flor; mas la palabra del Dios nuestro permanece para siempre.'),
  VersiculoDiario(55, 2, 22, 22, TemaVersiculo.tentacion, 'Huye también de las pasiones juveniles, y sigue la justicia, la fe, el amor y la paz, con los que de corazón limpio invocan al Señor.'),
  VersiculoDiario(45, 3, 23, 24, TemaVersiculo.gracia, 'Por cuanto todos pecaron, y están destituidos de la gloria de Dios, siendo justificados gratuitamente por su gracia, mediante la redención que es en Cristo Jesús,'),
  VersiculoDiario(45, 5, 1, 1, TemaVersiculo.paz, 'Justificados, pues, por la fe, tenemos paz para con Dios por medio de nuestro Señor Jesucristo;'),
  VersiculoDiario(33, 7, 19, 19, TemaVersiculo.perdon, 'Él volverá a tener misericordia de nosotros; sepultará nuestras iniquidades, y echará en lo profundo del mar todos nuestros pecados.'),
  VersiculoDiario(19, 46, 1, 1, TemaVersiculo.fortaleza, 'Dios es nuestro amparo y fortaleza, Nuestro pronto auxilio en las tribulaciones.'),
  VersiculoDiario(50, 4, 4, 4, TemaVersiculo.gozo, 'Regocijaos en el Señor siempre. Otra vez digo: ¡Regocijaos!'),
  VersiculoDiario(62, 3, 1, 1, TemaVersiculo.identidad, 'Mirad cuál amor nos ha dado el Padre, para que seamos llamados hijos de Dios; por esto el mundo no nos conoce, porque no le conoció a él.'),
  VersiculoDiario(23, 40, 31, 31, TemaVersiculo.esperanza, 'Pero los que esperan a Jehová tendrán nuevas fuerzas; levantarán alas como las águilas; correrán, y no se cansarán; caminarán, y no se fatigarán.'),
  VersiculoDiario(62, 5, 14, 14, TemaVersiculo.oracion, 'Y esta es la confianza que tenemos en él, que si pedimos alguna cosa conforme a su voluntad, él nos oye.'),
  VersiculoDiario(45, 10, 17, 17, TemaVersiculo.fe, 'Así que la fe es por el oír, y el oír, por la palabra de Dios.'),
  VersiculoDiario(43, 8, 36, 36, TemaVersiculo.victoria, 'Así que, si el Hijo os libertare, seréis verdaderamente libres.'),
  VersiculoDiario(62, 4, 10, 10, TemaVersiculo.amor, 'En esto consiste el amor: no en que nosotros hayamos amado a Dios, sino en que él nos amó a nosotros, y envió a su Hijo en propiciación por nuestros pecados.'),
  VersiculoDiario(46, 6, 19, 20, TemaVersiculo.pureza, '¿O ignoráis que vuestro cuerpo es templo del Espíritu Santo, el cual está en vosotros, el cual tenéis de Dios, y que no sois vuestros? Porque habéis sido comprados por precio; glorificad, pues, a Dios en vuestro cuerpo y en vuestro espíritu, los cuales son de Dios.'),
  VersiculoDiario(6, 1, 8, 8, TemaVersiculo.palabra, 'Nunca se apartará de tu boca este libro de la ley, sino que de día y de noche meditarás en él, para que guardes y hagas conforme a todo lo que en él está escrito; porque entonces harás prosperar tu camino, y todo te saldrá bien.'),
  VersiculoDiario(19, 42, 11, 11, TemaVersiculo.esperanza, '¿Por qué te abates, oh alma mía, Y por qué te turbas dentro de mí? Espera en Dios; porque aún he de alabarle, Salvación mía y Dios mío.'),
  VersiculoDiario(60, 2, 9, 9, TemaVersiculo.identidad, 'Mas vosotros sois linaje escogido, real sacerdocio, nación santa, pueblo adquirido por Dios, para que anunciéis las virtudes de aquel que os llamó de las tinieblas a su luz admirable;'),
  VersiculoDiario(62, 4, 16, 16, TemaVersiculo.amor, 'Y nosotros hemos conocido y creído el amor que Dios tiene para con nosotros. Dios es amor; y el que permanece en amor, permanece en Dios, y Dios en él.'),
  VersiculoDiario(23, 40, 29, 29, TemaVersiculo.fortaleza, 'Él da esfuerzo al cansado, y multiplica las fuerzas al que no tiene ningunas.'),
  VersiculoDiario(52, 4, 3, 3, TemaVersiculo.pureza, 'Pues la voluntad de Dios es vuestra santificación; que os apartéis de fornicación;'),
  VersiculoDiario(59, 5, 16, 16, TemaVersiculo.oracion, 'Confesaos vuestras ofensas unos a otros, y orad unos por otros, para que seáis sanados. La oración eficaz del justo puede mucho.'),
  VersiculoDiario(62, 4, 4, 4, TemaVersiculo.victoria, 'Hijitos, vosotros sois de Dios, y los habéis vencido; porque mayor es el que está en vosotros, que el que está en el mundo.'),
  VersiculoDiario(23, 43, 25, 25, TemaVersiculo.perdon, 'Yo, yo soy el que borro tus rebeliones por amor de mí mismo, y no me acordaré de tus pecados.'),
  VersiculoDiario(41, 9, 23, 23, TemaVersiculo.fe, 'Jesús le dijo: Si puedes creer, al que cree todo le es posible.'),
  VersiculoDiario(4, 6, 24, 26, TemaVersiculo.paz, 'Jehová te bendiga, y te guarde; Jehová haga resplandecer su rostro sobre ti, y tenga de ti misericordia; Jehová alce sobre ti su rostro, y ponga en ti paz.'),
  VersiculoDiario(46, 6, 18, 18, TemaVersiculo.tentacion, 'Huid de la fornicación. Cualquier otro pecado que el hombre cometa, está fuera del cuerpo; mas el que fornica, contra su propio cuerpo peca.'),
  VersiculoDiario(45, 5, 20, 20, TemaVersiculo.gracia, 'Pero la ley se introdujo para que el pecado abundase; mas cuando el pecado abundó, sobreabundó la gracia;'),
  VersiculoDiario(19, 100, 4, 4, TemaVersiculo.gozo, 'Entrad por sus puertas con acción de gracias, Por sus atrios con alabanza; Alabadle, bendecid su nombre.'),
  VersiculoDiario(47, 2, 14, 14, TemaVersiculo.victoria, 'Mas a Dios gracias, el cual nos lleva siempre en triunfo en Cristo Jesús, y por medio de nosotros manifiesta en todo lugar el olor de su conocimiento.'),
  VersiculoDiario(19, 145, 18, 18, TemaVersiculo.oracion, 'Cercano está Jehová a todos los que le invocan, A todos los que le invocan de veras.'),
  VersiculoDiario(62, 4, 19, 19, TemaVersiculo.amor, 'Nosotros le amamos a él, porque él nos amó primero.'),
  VersiculoDiario(49, 2, 10, 10, TemaVersiculo.identidad, 'Porque somos hechura suya, creados en Cristo Jesús para buenas obras, las cuales Dios preparó de antemano para que anduviésemos en ellas.'),
  VersiculoDiario(49, 4, 32, 32, TemaVersiculo.perdon, 'Antes sed benignos unos con otros, misericordiosos, perdonándoos unos a otros, como Dios también os perdonó a vosotros en Cristo.'),
  VersiculoDiario(19, 30, 11, 11, TemaVersiculo.gozo, 'Has cambiado mi lamento en baile; Desataste mi cilicio, y me ceñiste de alegría.'),
  VersiculoDiario(19, 1, 1, 2, TemaVersiculo.palabra, 'Bienaventurado el varón que no anduvo en consejo de malos, Ni estuvo en camino de pecadores, Ni en silla de escarnecedores se ha sentado; Sino que en la ley de Jehová está su delicia, Y en su ley medita de día y de noche.'),
  VersiculoDiario(48, 5, 16, 16, TemaVersiculo.tentacion, 'Digo, pues: Andad en el Espíritu, y no satisfagáis los deseos de la carne.'),
  VersiculoDiario(45, 6, 14, 14, TemaVersiculo.gracia, 'Porque el pecado no se enseñoreará de vosotros; pues no estáis bajo la ley, sino bajo la gracia.'),
  VersiculoDiario(19, 4, 8, 8, TemaVersiculo.paz, 'En paz me acostaré, y asimismo dormiré; Porque solo tú, Jehová, me haces vivir confiado.'),
  VersiculoDiario(45, 8, 28, 28, TemaVersiculo.esperanza, 'Y sabemos que a los que aman a Dios, todas las cosas les ayudan a bien, esto es, a los que conforme a su propósito son llamados.'),
  VersiculoDiario(52, 4, 7, 7, TemaVersiculo.pureza, 'Pues no nos ha llamado Dios a inmundicia, sino a santificación.'),
  VersiculoDiario(55, 1, 7, 7, TemaVersiculo.fortaleza, 'Porque no nos ha dado Dios espíritu de cobardía, sino de poder, de amor y de dominio propio.'),
  VersiculoDiario(19, 37, 5, 5, TemaVersiculo.fe, 'Encomienda a Jehová tu camino, Y confía en él; y él hará.'),
  VersiculoDiario(19, 31, 24, 24, TemaVersiculo.esperanza, 'Esforzaos todos vosotros los que esperáis en Jehová, Y tome aliento vuestro corazón.'),
  VersiculoDiario(19, 1, 3, 3, TemaVersiculo.palabra, 'Será como árbol plantado junto a corrientes de aguas, Que da su fruto en su tiempo, Y su hoja no cae; Y todo lo que hace, prosperará.'),
  VersiculoDiario(58, 4, 16, 16, TemaVersiculo.gracia, 'Acerquémonos, pues, confiadamente al trono de la gracia, para alcanzar misericordia y hallar gracia para el oportuno socorro.'),
  VersiculoDiario(19, 18, 2, 2, TemaVersiculo.fortaleza, 'Jehová, roca mía y castillo mío, y mi libertador; Dios mío, fortaleza mía, en él confiaré; Mi escudo, y la fuerza de mi salvación, mi alto refugio.'),
  VersiculoDiario(23, 26, 4, 4, TemaVersiculo.fe, 'Confiad en Jehová perpetuamente, porque en Jehová el Señor está la fortaleza de los siglos.'),
  VersiculoDiario(60, 1, 15, 16, TemaVersiculo.pureza, 'Sino, como aquel que os llamó es santo, sed también vosotros santos en toda vuestra manera de vivir; porque escrito está: Sed santos, porque yo soy santo.'),
  VersiculoDiario(45, 8, 16, 16, TemaVersiculo.identidad, 'El Espíritu mismo da testimonio a nuestro espíritu, de que somos hijos de Dios.'),
  VersiculoDiario(45, 13, 14, 14, TemaVersiculo.tentacion, 'Sino vestíos del Señor Jesucristo, y no proveáis para los deseos de la carne.'),
  VersiculoDiario(19, 126, 3, 3, TemaVersiculo.gozo, 'Grandes cosas ha hecho Jehová con nosotros; Estaremos alegres.'),
  VersiculoDiario(19, 34, 17, 17, TemaVersiculo.oracion, 'Claman los justos, y Jehová oye, Y los libra de todas sus angustias.'),
  VersiculoDiario(51, 3, 15, 15, TemaVersiculo.paz, 'Y la paz de Dios gobierne en vuestros corazones, a la que asimismo fuisteis llamados en un solo cuerpo; y sed agradecidos.'),
  VersiculoDiario(45, 8, 31, 31, TemaVersiculo.victoria, '¿Qué, pues, diremos a esto? Si Dios es por nosotros, ¿quién contra nosotros?'),
  VersiculoDiario(51, 3, 13, 13, TemaVersiculo.perdon, 'Soportándoos unos a otros, y perdonándoos unos a otros si alguno tuviere queja contra otro. De la manera que Cristo os perdonó, así también hacedlo vosotros.'),
  VersiculoDiario(24, 31, 3, 3, TemaVersiculo.amor, 'Jehová se manifestó a mí hace ya mucho tiempo, diciendo: Con amor eterno te he amado; por tanto, te prolongué mi misericordia.'),
  VersiculoDiario(48, 4, 7, 7, TemaVersiculo.identidad, 'Así que ya no eres esclavo, sino hijo; y si hijo, también heredero de Dios por medio de Cristo.'),
  VersiculoDiario(43, 1, 16, 16, TemaVersiculo.gracia, 'Porque de su plenitud tomamos todos, y gracia sobre gracia.'),
  VersiculoDiario(19, 56, 3, 3, TemaVersiculo.fe, 'En el día que temo, Yo en ti confío.'),
  VersiculoDiario(40, 11, 28, 30, TemaVersiculo.paz, 'Venid a mí todos los que estáis trabajados y cargados, y yo os haré descansar. Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso para vuestras almas; porque mi yugo es fácil, y ligera mi carga.'),
  VersiculoDiario(35, 3, 18, 18, TemaVersiculo.gozo, 'Con todo, yo me alegraré en Jehová, Y me gozaré en el Dios de mi salvación.'),
  VersiculoDiario(48, 5, 1, 1, TemaVersiculo.victoria, 'Estad, pues, firmes en la libertad con que Cristo nos hizo libres, y no estéis otra vez sujetos al yugo de esclavitud.'),
  VersiculoDiario(45, 12, 2, 2, TemaVersiculo.tentacion, 'No os conforméis a este siglo, sino transformaos por medio de la renovación de vuestro entendimiento, para que comprobéis cuál sea la buena voluntad de Dios, agradable y perfecta.'),
  VersiculoDiario(44, 3, 19, 19, TemaVersiculo.perdon, 'Así que, arrepentíos y convertíos, para que sean borrados vuestros pecados; para que vengan de la presencia del Señor tiempos de refrigerio,'),
  VersiculoDiario(58, 12, 14, 14, TemaVersiculo.pureza, 'Seguid la paz con todos, y la santidad, sin la cual nadie verá al Señor.'),
  VersiculoDiario(36, 3, 17, 17, TemaVersiculo.amor, 'Jehová está en medio de ti, poderoso, él salvará; se gozará sobre ti con alegría, callará de amor, se regocijará sobre ti con cánticos.'),
  VersiculoDiario(38, 9, 12, 12, TemaVersiculo.esperanza, 'Volveos a la fortaleza, oh prisioneros de esperanza; hoy también os anuncio que os restauraré el doble.'),
  VersiculoDiario(40, 4, 4, 4, TemaVersiculo.palabra, 'Él respondió y dijo: Escrito está: No solo de pan vivirá el hombre, sino de toda palabra que sale de la boca de Dios.'),
  VersiculoDiario(40, 6, 6, 6, TemaVersiculo.oracion, 'Mas tú, cuando ores, entra en tu aposento, y cerrada la puerta, ora a tu Padre que está en secreto; y tu Padre que ve en lo secreto te recompensará en público.'),
  VersiculoDiario(19, 28, 7, 7, TemaVersiculo.fortaleza, 'Jehová es mi fortaleza y mi escudo; En él confió mi corazón, y fui ayudado, Por lo que se gozó mi corazón, Y con mi cántico le alabaré.'),
  VersiculoDiario(52, 5, 17, 17, TemaVersiculo.oracion, 'Orad sin cesar.'),
  VersiculoDiario(47, 9, 8, 8, TemaVersiculo.gracia, 'Y poderoso es Dios para hacer que abunde en vosotros toda gracia, a fin de que, teniendo siempre en todas las cosas todo lo suficiente, abundéis para toda buena obra;'),
  VersiculoDiario(47, 5, 7, 7, TemaVersiculo.fe, '(porque por fe andamos, no por vista);'),
  VersiculoDiario(49, 6, 10, 10, TemaVersiculo.fortaleza, 'Por lo demás, hermanos míos, fortaleceos en el Señor, y en el poder de su fuerza.'),
  VersiculoDiario(51, 3, 3, 3, TemaVersiculo.identidad, 'Porque habéis muerto, y vuestra vida está escondida con Cristo en Dios.'),
  VersiculoDiario(19, 24, 3, 4, TemaVersiculo.pureza, '¿Quién subirá al monte de Jehová? ¿Y quién estará en su lugar santo? El limpio de manos y puro de corazón; El que no ha elevado su alma a cosas vanas, Ni jurado con engaño.'),
  VersiculoDiario(23, 49, 15, 15, TemaVersiculo.amor, '¿Se olvidará la mujer de lo que dio a luz, para dejar de compadecerse del hijo de su vientre? Aunque olvide ella, yo nunca me olvidaré de ti.'),
  VersiculoDiario(45, 5, 5, 5, TemaVersiculo.esperanza, 'Y la esperanza no avergüenza; porque el amor de Dios ha sido derramado en nuestros corazones por el Espíritu Santo que nos fue dado.'),
  VersiculoDiario(19, 119, 11, 11, TemaVersiculo.tentacion, 'En mi corazón he guardado tus dichos, Para no pecar contra ti.'),
  VersiculoDiario(19, 103, 1, 1, TemaVersiculo.gozo, 'Bendice, alma mía, a Jehová, Y bendiga todo mi ser su santo nombre.'),
  VersiculoDiario(19, 23, 1, 2, TemaVersiculo.paz, 'Jehová es mi pastor; nada me faltará. En lugares de delicados pastos me hará descansar; Junto a aguas de reposo me pastoreará.'),
  VersiculoDiario(40, 24, 35, 35, TemaVersiculo.palabra, 'El cielo y la tierra pasarán, pero mis palabras no pasarán.'),
  VersiculoDiario(19, 32, 5, 5, TemaVersiculo.perdon, 'Mi pecado te declaré, y no encubrí mi iniquidad. Dije: Confesaré mis transgresiones a Jehová; Y tú perdonaste la maldad de mi pecado.'),
  VersiculoDiario(66, 12, 11, 11, TemaVersiculo.victoria, 'Y ellos le han vencido por medio de la sangre del Cordero y de la palabra del testimonio de ellos, y menospreciaron sus vidas hasta la muerte.'),
  VersiculoDiario(19, 103, 11, 11, TemaVersiculo.amor, 'Porque como la altura de los cielos sobre la tierra, Engrandeció su misericordia sobre los que le temen.'),
  VersiculoDiario(49, 1, 7, 7, TemaVersiculo.gracia, 'En quien tenemos redención por su sangre, el perdón de pecados según las riquezas de su gracia,'),
  VersiculoDiario(23, 55, 11, 11, TemaVersiculo.palabra, 'Así será mi palabra que sale de mi boca; no volverá a mí vacía, sino que hará lo que yo quiero, y será prosperada en aquello para que la envié.'),
  VersiculoDiario(19, 130, 5, 5, TemaVersiculo.esperanza, 'Esperé yo a Jehová, esperó mi alma; En su palabra he esperado.'),
  VersiculoDiario(19, 73, 26, 26, TemaVersiculo.fortaleza, 'Mi carne y mi corazón desfallecen; Mas la roca de mi corazón y mi porción es Dios para siempre.'),
  VersiculoDiario(45, 8, 15, 15, TemaVersiculo.identidad, 'Pues no habéis recibido el espíritu de esclavitud para estar otra vez en temor, sino que habéis recibido el espíritu de adopción, por el cual clamamos: ¡Abba, Padre!'),
  VersiculoDiario(58, 12, 2, 2, TemaVersiculo.fe, 'Puestos los ojos en Jesús, el autor y consumador de la fe, el cual por el gozo puesto delante de él sufrió la cruz, menospreciando el oprobio, y se sentó a la diestra del trono de Dios.'),
  VersiculoDiario(58, 2, 18, 18, TemaVersiculo.tentacion, 'Pues en cuanto él mismo padeció siendo tentado, es poderoso para socorrer a los que son tentados.'),
  VersiculoDiario(19, 101, 3, 3, TemaVersiculo.pureza, 'No pondré delante de mis ojos cosa injusta. Aborrezco la obra de los que se desvían; Ninguno de ellos se acercará a mí.'),
  VersiculoDiario(19, 32, 1, 1, TemaVersiculo.perdon, 'Bienaventurado aquel cuya transgresión ha sido perdonada, y cubierto su pecado.'),
  VersiculoDiario(45, 8, 26, 26, TemaVersiculo.oracion, 'Y de igual manera el Espíritu nos ayuda en nuestra debilidad; pues qué hemos de pedir como conviene, no lo sabemos, pero el Espíritu mismo intercede por nosotros con gemidos indecibles.'),
  VersiculoDiario(23, 32, 17, 17, TemaVersiculo.paz, 'Y el efecto de la justicia será paz; y la labor de la justicia, reposo y seguridad para siempre.'),
  VersiculoDiario(19, 34, 1, 1, TemaVersiculo.gozo, 'Bendeciré a Jehová en todo tiempo; Su alabanza estará de continuo en mi boca.'),
  VersiculoDiario(33, 7, 8, 8, TemaVersiculo.victoria, 'Tú, enemiga mía, no te alegres de mí, porque aunque caí, me levantaré; aunque more en tinieblas, Jehová será mi luz.'),
  VersiculoDiario(19, 95, 1, 1, TemaVersiculo.gozo, 'Venid, aclamemos alegremente a Jehová; Cantemos con júbilo a la roca de nuestra salvación.'),
  VersiculoDiario(23, 12, 2, 2, TemaVersiculo.fortaleza, 'He aquí Dios es salvación mía; me aseguraré y no temeré; porque mi fortaleza y mi canción es JAH Jehová, quien ha sido salvación para mí.'),
  VersiculoDiario(18, 31, 1, 1, TemaVersiculo.pureza, 'Hice pacto con mis ojos; ¿Cómo, pues, había yo de mirar a una virgen?'),
  VersiculoDiario(20, 28, 13, 13, TemaVersiculo.perdon, 'El que encubre sus pecados no prosperará; Mas el que los confiesa y se aparta alcanzará misericordia.'),
  VersiculoDiario(53, 3, 16, 16, TemaVersiculo.paz, 'Y el mismo Señor de paz os dé siempre paz en toda manera. El Señor sea con todos vosotros.'),
  VersiculoDiario(20, 23, 18, 18, TemaVersiculo.esperanza, 'Porque ciertamente hay fin, Y tu esperanza no será cortada.'),
  VersiculoDiario(19, 9, 10, 10, TemaVersiculo.fe, 'En ti confiarán los que conocen tu nombre, Por cuanto tú, oh Jehová, no desamparaste a los que te buscaron.'),
  VersiculoDiario(19, 19, 7, 7, TemaVersiculo.palabra, 'La ley de Jehová es perfecta, que convierte el alma; El testimonio de Jehová es fiel, que hace sabio al sencillo.'),
  VersiculoDiario(20, 24, 16, 16, TemaVersiculo.victoria, 'Porque siete veces cae el justo, y vuelve a levantarse; Mas los impíos caerán en el mal.'),
  VersiculoDiario(19, 55, 17, 17, TemaVersiculo.oracion, 'Tarde y mañana y a mediodía oraré y clamaré, Y él oirá mi voz.'),
  VersiculoDiario(45, 8, 1, 1, TemaVersiculo.gracia, 'Ahora, pues, ninguna condenación hay para los que están en Cristo Jesús, los que no andan conforme a la carne, sino conforme al Espíritu.'),
  VersiculoDiario(19, 103, 13, 13, TemaVersiculo.amor, 'Como el padre se compadece de los hijos, Se compadece Jehová de los que le temen.'),
  VersiculoDiario(43, 15, 15, 15, TemaVersiculo.identidad, 'Ya no os llamaré siervos, porque el siervo no sabe lo que hace su señor; pero os he llamado amigos, porque todas las cosas que oí de mi Padre, os las he dado a conocer.'),
  VersiculoDiario(58, 4, 15, 15, TemaVersiculo.tentacion, 'Porque no tenemos un sumo sacerdote que no pueda compadecerse de nuestras debilidades, sino uno que fue tentado en todo según nuestra semejanza, pero sin pecado.'),
  VersiculoDiario(19, 19, 8, 8, TemaVersiculo.palabra, 'Los mandamientos de Jehová son rectos, que alegran el corazón; El precepto de Jehová es puro, que alumbra los ojos.'),
  VersiculoDiario(59, 1, 12, 12, TemaVersiculo.tentacion, 'Bienaventurado el varón que soporta la tentación; porque cuando haya resistido la prueba, recibirá la corona de vida, que Dios ha prometido a los que le aman.'),
  VersiculoDiario(19, 27, 1, 1, TemaVersiculo.fortaleza, 'Jehová es mi luz y mi salvación; ¿de quién temeré? Jehová es la fortaleza de mi vida; ¿de quién he de atemorizarme?'),
  VersiculoDiario(19, 5, 3, 3, TemaVersiculo.oracion, 'Oh Jehová, de mañana oirás mi voz; De mañana me presentaré delante de ti, y esperaré.'),
  VersiculoDiario(43, 15, 9, 9, TemaVersiculo.amor, 'Como el Padre me ha amado, así también yo os he amado; permaneced en mi amor.'),
  VersiculoDiario(43, 15, 16, 16, TemaVersiculo.identidad, 'No me elegisteis vosotros a mí, sino que yo os elegí a vosotros, y os he puesto para que vayáis y llevéis fruto, y vuestro fruto permanezca; para que todo lo que pidiereis al Padre en mi nombre, él os lo dé.'),
  VersiculoDiario(5, 20, 4, 4, TemaVersiculo.victoria, 'Porque Jehová vuestro Dios va con vosotros, para pelear por vosotros contra vuestros enemigos, para salvaros.'),
  VersiculoDiario(19, 150, 6, 6, TemaVersiculo.gozo, 'Todo lo que respira alabe a JAH. Aleluya.'),
  VersiculoDiario(19, 119, 165, 165, TemaVersiculo.paz, 'Mucha paz tienen los que aman tu ley, Y no hay para ellos tropiezo.'),
  VersiculoDiario(55, 1, 9, 9, TemaVersiculo.gracia, 'Quien nos salvó y llamó con llamamiento santo, no conforme a nuestras obras, sino según el propósito suyo y la gracia que nos fue dada en Cristo Jesús antes de los tiempos de los siglos,'),
  VersiculoDiario(45, 12, 1, 1, TemaVersiculo.pureza, 'Así que, hermanos, os ruego por las misericordias de Dios, que presentéis vuestros cuerpos en sacrificio vivo, santo, agradable a Dios, que es vuestro culto racional.'),
  VersiculoDiario(19, 20, 7, 7, TemaVersiculo.fe, 'Estos confían en carros, y aquellos en caballos; Mas nosotros del nombre de Jehová nuestro Dios tendremos memoria.'),
  VersiculoDiario(23, 43, 19, 19, TemaVersiculo.esperanza, 'He aquí que yo hago cosa nueva; pronto saldrá a luz; ¿no la conoceréis? Otra vez abriré camino en el desierto, y ríos en la soledad.'),
  VersiculoDiario(19, 51, 1, 2, TemaVersiculo.perdon, 'Ten piedad de mí, oh Dios, conforme a tu misericordia; Conforme a la multitud de tus piedades borra mis rebeliones. Lávame más y más de mi maldad, Y límpiame de mi pecado.'),
  VersiculoDiario(19, 119, 89, 89, TemaVersiculo.palabra, 'Para siempre, oh Jehová, Permanece tu palabra en los cielos.'),
  VersiculoDiario(2, 14, 14, 14, TemaVersiculo.victoria, 'Jehová peleará por vosotros, y vosotros estaréis tranquilos.'),
  VersiculoDiario(23, 9, 6, 6, TemaVersiculo.paz, 'Porque un niño nos es nacido, hijo nos es dado, y el principado sobre su hombro; y se llamará su nombre Admirable, Consejero, Dios Fuerte, Padre Eterno, Príncipe de Paz.'),
  VersiculoDiario(47, 7, 1, 1, TemaVersiculo.pureza, 'Así que, amados, puesto que tenemos tales promesas, limpiémonos de toda contaminación de carne y de espíritu, perfeccionando la santidad en el temor de Dios.'),
  VersiculoDiario(5, 31, 6, 6, TemaVersiculo.fortaleza, 'Esforzaos y cobrad ánimo; no temáis, ni tengáis miedo de ellos, porque Jehová tu Dios es el que va contigo; no te dejará, ni te desamparará.'),
  VersiculoDiario(43, 14, 13, 14, TemaVersiculo.oracion, 'Y todo lo que pidiereis al Padre en mi nombre, lo haré, para que el Padre sea glorificado en el Hijo. Si algo pidiereis en mi nombre, yo lo haré.'),
  VersiculoDiario(19, 86, 5, 5, TemaVersiculo.perdon, 'Porque tú, Señor, eres bueno y perdonador, Y grande en misericordia para con todos los que te invocan.'),
  VersiculoDiario(43, 15, 13, 13, TemaVersiculo.amor, 'Nadie tiene mayor amor que este, que uno ponga su vida por sus amigos.'),
  VersiculoDiario(19, 125, 1, 1, TemaVersiculo.fe, 'Los que confían en Jehová son como el monte de Sion, Que no se mueve, sino que permanece para siempre.'),
  VersiculoDiario(48, 3, 26, 26, TemaVersiculo.identidad, 'Pues todos sois hijos de Dios por la fe en Cristo Jesús;'),
  VersiculoDiario(19, 147, 3, 3, TemaVersiculo.esperanza, 'Él sana a los quebrantados de corazón, Y venda sus heridas.'),
  VersiculoDiario(43, 15, 11, 11, TemaVersiculo.gozo, 'Estas cosas os he hablado, para que mi gozo esté en vosotros, y vuestro gozo sea cumplido.'),
  VersiculoDiario(60, 5, 8, 9, TemaVersiculo.tentacion, 'Sed sobrios, y velad; porque vuestro adversario el diablo, como león rugiente, anda alrededor buscando a quien devorar; al cual resistid firmes en la fe, sabiendo que los mismos padecimientos se van cumpliendo en vuestros hermanos en todo el mundo.'),
  VersiculoDiario(56, 3, 5, 5, TemaVersiculo.gracia, 'Nos salvó, no por obras de justicia que nosotros hubiéramos hecho, sino por su misericordia, por el lavamiento de la regeneración y por la renovación en el Espíritu Santo,'),
  VersiculoDiario(25, 3, 25, 25, TemaVersiculo.esperanza, 'Bueno es Jehová a los que en él esperan, al alma que le busca.'),
  VersiculoDiario(19, 119, 103, 103, TemaVersiculo.palabra, '¡Cuán dulces son a mi paladar tus palabras! Más que la miel a mi boca.'),
  VersiculoDiario(49, 6, 16, 16, TemaVersiculo.fe, 'Sobre todo, tomad el escudo de la fe, con que podáis apagar todos los dardos de fuego del maligno.'),
  VersiculoDiario(19, 59, 16, 16, TemaVersiculo.fortaleza, 'Pero yo cantaré de tu poder, Y alabaré de mañana tu misericordia; Porque has sido mi amparo Y refugio en el día de mi angustia.'),
  VersiculoDiario(62, 5, 5, 5, TemaVersiculo.victoria, '¿Quién es el que vence al mundo, sino el que cree que Jesús es el Hijo de Dios?'),
  VersiculoDiario(47, 10, 5, 5, TemaVersiculo.tentacion, 'Derribando argumentos y toda altivez que se levanta contra el conocimiento de Dios, y llevando cautivo todo pensamiento a la obediencia a Cristo,'),
  VersiculoDiario(41, 11, 24, 24, TemaVersiculo.oracion, 'Por tanto, os digo que todo lo que pidiereis orando, creed que lo recibiréis, y os vendrá.'),
  VersiculoDiario(20, 3, 24, 24, TemaVersiculo.paz, 'Cuando te acuestes, no tendrás temor, Sino que te acostarás, y tu sueño será grato.'),
  VersiculoDiario(62, 3, 3, 3, TemaVersiculo.pureza, 'Y todo aquel que tiene esta esperanza en él, se purifica a sí mismo, así como él es puro.'),
  VersiculoDiario(19, 36, 7, 7, TemaVersiculo.amor, '¡Cuán preciosa, oh Dios, es tu misericordia! Por eso los hijos de los hombres se amparan bajo la sombra de tus alas.'),
  VersiculoDiario(59, 1, 2, 3, TemaVersiculo.gozo, 'Hermanos míos, tened por sumo gozo cuando os halléis en diversas pruebas, sabiendo que la prueba de vuestra fe produce paciencia.'),
  VersiculoDiario(59, 4, 6, 6, TemaVersiculo.gracia, 'Pero él da mayor gracia. Por esto dice: Dios resiste a los soberbios, y da gracia a los humildes.'),
  VersiculoDiario(49, 4, 24, 24, TemaVersiculo.identidad, 'Y vestíos del nuevo hombre, creado según Dios en la justicia y santidad de la verdad.'),
  VersiculoDiario(19, 130, 3, 4, TemaVersiculo.perdon, 'JAH, si mirares a los pecados, ¿Quién, oh Señor, podrá mantenerse? Pero en ti hay perdón, Para que seas reverenciado.'),
  VersiculoDiario(51, 4, 2, 2, TemaVersiculo.oracion, 'Perseverad en la oración, velando en ella con acción de gracias;'),
  VersiculoDiario(19, 60, 12, 12, TemaVersiculo.victoria, 'En Dios haremos proezas, Y él hollará a nuestros enemigos.'),
  VersiculoDiario(3, 20, 7, 7, TemaVersiculo.pureza, 'Santificaos, pues, y sed santos, porque yo Jehová soy vuestro Dios.'),
  VersiculoDiario(23, 61, 10, 10, TemaVersiculo.gozo, 'En gran manera me gozaré en Jehová, mi alma se alegrará en mi Dios; porque me vistió con vestiduras de salvación, me rodeó de manto de justicia, como a novio me atavió, y como a novia adornada con sus joyas.'),
  VersiculoDiario(49, 5, 8, 8, TemaVersiculo.identidad, 'Porque en otro tiempo erais tinieblas, mas ahora sois luz en el Señor; andad como hijos de luz'),
  VersiculoDiario(19, 119, 130, 130, TemaVersiculo.palabra, 'La exposición de tus palabras alumbra; Hace entender a los simples.'),
  VersiculoDiario(19, 33, 20, 20, TemaVersiculo.esperanza, 'Nuestra alma espera a Jehová; Nuestra ayuda y nuestro escudo es él.'),
  VersiculoDiario(20, 25, 28, 28, TemaVersiculo.tentacion, 'Como ciudad derribada y sin muro Es el hombre cuyo espíritu no tiene rienda.'),
  VersiculoDiario(23, 54, 10, 10, TemaVersiculo.paz, 'Porque los montes se moverán, y los collados temblarán, pero no se apartará de ti mi misericordia, ni el pacto de mi paz se quebrantará, dijo Jehová, el que tiene misericordia de ti.'),
  VersiculoDiario(60, 5, 10, 10, TemaVersiculo.gracia, 'Mas el Dios de toda gracia, que nos llamó a su gloria eterna en Jesucristo, después que hayáis padecido un poco de tiempo, él mismo os perfeccione, afirme, fortalezca y establezca.'),
  VersiculoDiario(28, 14, 4, 4, TemaVersiculo.amor, 'Yo sanaré su rebelión, los amaré de pura gracia; porque mi ira se apartó de ellos.'),
  VersiculoDiario(19, 29, 11, 11, TemaVersiculo.fortaleza, 'Jehová dará poder a su pueblo; Jehová bendecirá a su pueblo con paz.'),
  VersiculoDiario(43, 11, 40, 40, TemaVersiculo.fe, 'Jesús le dijo: ¿No te he dicho que si crees, verás la gloria de Dios?'),
  VersiculoDiario(40, 6, 14, 14, TemaVersiculo.perdon, 'Porque si perdonáis a los hombres sus ofensas, os perdonará también a vosotros vuestro Padre celestial;'),
  VersiculoDiario(66, 21, 7, 7, TemaVersiculo.victoria, 'El que venciere heredará todas las cosas, y yo seré su Dios, y él será mi hijo.'),
  VersiculoDiario(40, 6, 33, 33, TemaVersiculo.fe, 'Mas buscad primeramente el reino de Dios y su justicia, y todas estas cosas os serán añadidas.'),
  VersiculoDiario(19, 46, 10, 10, TemaVersiculo.paz, 'Estad quietos, y conoced que yo soy Dios; Seré exaltado entre las naciones; enaltecido seré en la tierra.'),
  VersiculoDiario(48, 5, 22, 23, TemaVersiculo.tentacion, 'Mas el fruto del Espíritu es amor, gozo, paz, paciencia, benignidad, bondad, fe, mansedumbre, templanza; contra tales cosas no hay ley.'),
  VersiculoDiario(54, 1, 15, 15, TemaVersiculo.gracia, 'Palabra fiel y digna de ser recibida por todos: que Cristo Jesús vino al mundo para salvar a los pecadores, de los cuales yo soy el primero.'),
  VersiculoDiario(24, 29, 12, 13, TemaVersiculo.oracion, 'Entonces me invocaréis, y vendréis y oraréis a mí, y yo os oiré; y me buscaréis y me hallaréis, porque me buscaréis de todo vuestro corazón.'),
  VersiculoDiario(40, 5, 14, 14, TemaVersiculo.identidad, 'Vosotros sois la luz del mundo; una ciudad asentada sobre un monte no se puede esconder.'),
  VersiculoDiario(50, 4, 8, 8, TemaVersiculo.pureza, 'Por lo demás, hermanos, todo lo que es verdadero, todo lo honesto, todo lo justo, todo lo puro, todo lo amable, todo lo que es de buen nombre; si hay virtud alguna, si algo digno de alabanza, en esto pensad.'),
  VersiculoDiario(19, 62, 5, 5, TemaVersiculo.esperanza, 'Alma mía, en Dios solamente reposa, Porque de él es mi esperanza.'),
  VersiculoDiario(51, 3, 17, 17, TemaVersiculo.gozo, 'Y todo lo que hacéis, sea de palabra o de hecho, hacedlo todo en el nombre del Señor Jesús, dando gracias a Dios Padre por medio de él.'),
  VersiculoDiario(2, 15, 2, 2, TemaVersiculo.fortaleza, 'Jehová es mi fortaleza y mi cántico, Y ha sido mi salvación. Este es mi Dios, y lo alabaré; Dios de mi padre, y lo enalteceré.'),
  VersiculoDiario(49, 5, 2, 2, TemaVersiculo.amor, 'Y andad en amor, como también Cristo nos amó, y se entregó a sí mismo por nosotros, ofrenda y sacrificio a Dios en olor fragante.'),
  VersiculoDiario(43, 8, 31, 32, TemaVersiculo.palabra, 'Dijo entonces Jesús a los judíos que habían creído en él: Si vosotros permaneciereis en mi palabra, seréis verdaderamente mis discípulos; y conoceréis la verdad, y la verdad os hará libres.'),
  VersiculoDiario(42, 15, 20, 20, TemaVersiculo.perdon, 'Y levantándose, vino a su padre. Y cuando aún estaba lejos, lo vio su padre, y fue movido a misericordia, y corrió, y se echó sobre su cuello, y le besó.'),
  VersiculoDiario(33, 7, 7, 7, TemaVersiculo.esperanza, 'Mas yo a Jehová miraré, esperaré al Dios de mi salvación; el Dios mío me oirá.'),
  VersiculoDiario(43, 17, 17, 17, TemaVersiculo.palabra, 'Santifícalos en tu verdad; tu palabra es verdad.'),
  VersiculoDiario(13, 16, 11, 11, TemaVersiculo.fortaleza, 'Buscad a Jehová y su poder; Buscad su rostro continuamente.'),
  VersiculoDiario(19, 139, 14, 14, TemaVersiculo.identidad, 'Te alabaré; porque formidables, maravillosas son tus obras; Estoy maravillado, Y mi alma lo sabe muy bien.'),
  VersiculoDiario(58, 8, 12, 12, TemaVersiculo.perdon, 'Porque seré propicio a sus injusticias, Y nunca más me acordaré de sus pecados y de sus iniquidades.'),
  VersiculoDiario(62, 3, 16, 16, TemaVersiculo.amor, 'En esto hemos conocido el amor, en que él puso su vida por nosotros; también nosotros debemos poner nuestras vidas por los hermanos.'),
  VersiculoDiario(20, 4, 23, 23, TemaVersiculo.pureza, 'Sobre toda cosa guardada, guarda tu corazón; Porque de él mana la vida.'),
  VersiculoDiario(50, 4, 19, 19, TemaVersiculo.fe, 'Mi Dios, pues, suplirá todo lo que os falta conforme a sus riquezas en gloria en Cristo Jesús.'),
  VersiculoDiario(47, 8, 9, 9, TemaVersiculo.gracia, 'Porque ya conocéis la gracia de nuestro Señor Jesucristo, que por amor a vosotros se hizo pobre, siendo rico, para que vosotros con su pobreza fueseis enriquecidos.'),
  VersiculoDiario(45, 16, 20, 20, TemaVersiculo.victoria, 'Y el Dios de paz aplastará en breve a Satanás bajo vuestros pies. La gracia de nuestro Señor Jesucristo sea con vosotros.'),
  VersiculoDiario(40, 5, 9, 9, TemaVersiculo.paz, 'Bienaventurados los pacificadores, porque ellos serán llamados hijos de Dios.'),
  VersiculoDiario(49, 5, 20, 20, TemaVersiculo.gozo, 'Dando siempre gracias por todo al Dios y Padre, en el nombre de nuestro Señor Jesucristo.'),
  VersiculoDiario(19, 62, 8, 8, TemaVersiculo.oracion, 'Esperad en él en todo tiempo, oh pueblos; Derramad delante de él vuestro corazón; Dios es nuestro refugio.'),
  VersiculoDiario(60, 2, 11, 11, TemaVersiculo.tentacion, 'Amados, yo os ruego como a extranjeros y peregrinos, que os abstengáis de los deseos carnales que batallan contra el alma,'),
  VersiculoDiario(51, 2, 15, 15, TemaVersiculo.victoria, 'Y despojando a los principados y a las potestades, los exhibió públicamente, triunfando sobre ellos en la cruz.'),
  VersiculoDiario(19, 103, 8, 8, TemaVersiculo.gracia, 'Misericordioso y clemente es Jehová; Lento para la ira, y grande en misericordia.'),
  VersiculoDiario(45, 12, 18, 18, TemaVersiculo.paz, 'Si es posible, en cuanto dependa de vosotros, estad en paz con todos los hombres.'),
  VersiculoDiario(45, 8, 18, 18, TemaVersiculo.esperanza, 'Pues tengo por cierto que las aflicciones del tiempo presente no son comparables con la gloria venidera que en nosotros ha de manifestarse.'),
  VersiculoDiario(19, 112, 7, 7, TemaVersiculo.fe, 'No tendrá temor de malas noticias; Su corazón está firme, confiado en Jehová.'),
  VersiculoDiario(19, 118, 14, 14, TemaVersiculo.fortaleza, 'Mi fortaleza y mi cántico es JAH, Y él me ha sido por salvación.'),
  VersiculoDiario(19, 63, 3, 3, TemaVersiculo.amor, 'Porque mejor es tu misericordia que la vida; Mis labios te alabarán.'),
  VersiculoDiario(23, 43, 1, 1, TemaVersiculo.identidad, 'Ahora, así dice Jehová, Creador tuyo, oh Jacob, y Formador tuyo, oh Israel: No temas, porque yo te redimí; te puse nombre, mío eres tú.'),
  VersiculoDiario(59, 4, 8, 8, TemaVersiculo.pureza, 'Acercaos a Dios, y él se acercará a vosotros. Pecadores, limpiad las manos; y vosotros los de doble ánimo, purificad vuestros corazones.'),
  VersiculoDiario(19, 107, 1, 1, TemaVersiculo.gozo, 'Alabad a Jehová, porque él es bueno; Porque para siempre es su misericordia.'),
  VersiculoDiario(14, 7, 14, 14, TemaVersiculo.oracion, 'Si se humillare mi pueblo, sobre el cual mi nombre es invocado, y oraren, y buscaren mi rostro, y se convirtieren de sus malos caminos; entonces yo oiré desde los cielos, y perdonaré sus pecados, y sanaré su tierra.'),
  VersiculoDiario(20, 4, 14, 15, TemaVersiculo.tentacion, 'No entres por la vereda de los impíos, Ni vayas por el camino de los malos. Déjala, no pases por ella; Apártate de ella, pasa.'),
  VersiculoDiario(59, 1, 22, 22, TemaVersiculo.palabra, 'Pero sed hacedores de la palabra, y no tan solamente oidores, engañándoos a vosotros mismos.'),
  VersiculoDiario(23, 55, 7, 7, TemaVersiculo.perdon, 'Deje el impío su camino, y el hombre inicuo sus pensamientos, y vuélvase a Jehová, el cual tendrá de él misericordia, y al Dios nuestro, el cual será amplio en perdonar.'),
  VersiculoDiario(40, 6, 13, 13, TemaVersiculo.tentacion, 'Y no nos metas en tentación, mas líbranos del mal; porque tuyo es el reino, y el poder, y la gloria, por todos los siglos. Amén.'),
  VersiculoDiario(19, 116, 1, 2, TemaVersiculo.oracion, 'Amo a Jehová, pues ha oído Mi voz y mis súplicas; Porque ha inclinado a mí su oído; Por tanto, le invocaré en todos mis días.'),
  VersiculoDiario(19, 121, 1, 2, TemaVersiculo.fe, 'Alzaré mis ojos a los montes; ¿De dónde vendrá mi socorro? Mi socorro viene de Jehová, Que hizo los cielos y la tierra.'),
  VersiculoDiario(19, 3, 5, 5, TemaVersiculo.paz, 'Yo me acosté y dormí, Y desperté, porque Jehová me sustentaba.'),
  VersiculoDiario(19, 145, 8, 9, TemaVersiculo.amor, 'Clemente y misericordioso es Jehová, Lento para la ira, y grande en misericordia. Bueno es Jehová para con todos, Y sus misericordias sobre todas sus obras.'),
  VersiculoDiario(46, 3, 16, 16, TemaVersiculo.pureza, '¿No sabéis que sois templo de Dios, y que el Espíritu de Dios mora en vosotros?'),
  VersiculoDiario(45, 6, 6, 6, TemaVersiculo.identidad, 'Sabiendo esto, que nuestro viejo hombre fue crucificado juntamente con él, para que el cuerpo del pecado sea destruido, a fin de que no sirvamos más al pecado.'),
  VersiculoDiario(51, 1, 13, 14, TemaVersiculo.perdon, 'El cual nos ha librado de la potestad de las tinieblas, y trasladado al reino de su amado Hijo, en quien tenemos redención por su sangre, el perdón de pecados.'),
  VersiculoDiario(45, 15, 4, 4, TemaVersiculo.palabra, 'Porque las cosas que se escribieron antes, para nuestra enseñanza se escribieron, a fin de que por la paciencia y la consolación de las Escrituras, tengamos esperanza.'),
  VersiculoDiario(47, 4, 17, 17, TemaVersiculo.esperanza, 'Porque esta leve tribulación momentánea produce en nosotros un cada vez más excelente y eterno peso de gloria;'),
  VersiculoDiario(45, 8, 2, 2, TemaVersiculo.victoria, 'Porque la ley del Espíritu de vida en Cristo Jesús me ha librado de la ley del pecado y de la muerte.'),
  VersiculoDiario(19, 138, 3, 3, TemaVersiculo.fortaleza, 'El día que clamé, me respondiste; Me fortaleciste con vigor en mi alma.'),
  VersiculoDiario(49, 2, 4, 5, TemaVersiculo.gracia, 'Pero Dios, que es rico en misericordia, por su gran amor con que nos amó, aun estando nosotros muertos en pecados, nos dio vida juntamente con Cristo (por gracia sois salvos),'),
  VersiculoDiario(19, 92, 1, 1, TemaVersiculo.gozo, 'Bueno es alabarte, oh Jehová, Y cantar salmos a tu nombre, oh Altísimo;'),
  VersiculoDiario(49, 6, 11, 11, TemaVersiculo.tentacion, 'Vestíos de toda la armadura de Dios, para que podáis estar firmes contra las asechanzas del diablo.'),
  VersiculoDiario(62, 1, 7, 7, TemaVersiculo.perdon, 'Pero si andamos en luz, como él está en luz, tenemos comunión unos con otros, y la sangre de Jesucristo su Hijo nos limpia de todo pecado.'),
  VersiculoDiario(23, 54, 17, 17, TemaVersiculo.victoria, 'Ninguna arma forjada contra ti prosperará, y condenarás toda lengua que se levante contra ti en juicio. Esta es la herencia de los siervos de Jehová, y su salvación de mí vendrá, dijo Jehová.'),
  VersiculoDiario(42, 19, 10, 10, TemaVersiculo.gracia, 'Porque el Hijo del Hombre vino a buscar y a salvar lo que se había perdido.'),
  VersiculoDiario(51, 3, 16, 16, TemaVersiculo.palabra, 'La palabra de Cristo more en abundancia en vosotros, enseñándoos y exhortándoos unos a otros en toda sabiduría, cantando con gracia en vuestros corazones al Señor con salmos e himnos y cánticos espirituales.'),
  VersiculoDiario(23, 65, 24, 24, TemaVersiculo.oracion, 'Y antes que clamen, responderé yo; mientras aún hablan, yo habré oído.'),
  VersiculoDiario(60, 1, 3, 3, TemaVersiculo.esperanza, 'Bendito el Dios y Padre de nuestro Señor Jesucristo, que según su grande misericordia nos hizo renacer para una esperanza viva, por la resurrección de Jesucristo de los muertos,'),
  VersiculoDiario(47, 4, 8, 9, TemaVersiculo.fortaleza, 'Que estamos atribulados en todo, mas no angustiados; en apuros, mas no desesperados; perseguidos, mas no desamparados; derribados, pero no destruidos;'),
  VersiculoDiario(23, 54, 8, 8, TemaVersiculo.amor, 'Con un poco de ira escondí mi rostro de ti por un momento; pero con misericordia eterna tendré compasión de ti, dijo Jehová tu Redentor.'),
  VersiculoDiario(19, 91, 1, 2, TemaVersiculo.fe, 'El que habita al abrigo del Altísimo Morará bajo la sombra del Omnipotente. Diré yo a Jehová: Esperanza mía, y castillo mío; Mi Dios, en quien confiaré.'),
  VersiculoDiario(19, 85, 8, 8, TemaVersiculo.paz, 'Escucharé lo que hablará Jehová Dios; Porque hablará paz a su pueblo y a sus santos, Para que no se vuelvan a la locura.'),
  VersiculoDiario(45, 6, 11, 11, TemaVersiculo.identidad, 'Así también vosotros consideraos muertos al pecado, pero vivos para Dios en Cristo Jesús, Señor nuestro.'),
  VersiculoDiario(19, 19, 14, 14, TemaVersiculo.pureza, 'Sean gratos los dichos de mi boca y la meditación de mi corazón delante de ti, Oh Jehová, roca mía, y redentor mío.'),
  VersiculoDiario(19, 9, 1, 2, TemaVersiculo.gozo, 'Te alabaré, oh Jehová, con todo mi corazón; Contaré todas tus maravillas. Me alegraré y me regocijaré en ti; Cantaré a tu nombre, oh Altísimo.'),
  VersiculoDiario(29, 2, 13, 13, TemaVersiculo.perdon, 'Rasgad vuestro corazón, y no vuestros vestidos, y convertíos a Jehová vuestro Dios; porque misericordioso es y clemente, tardo para la ira y grande en misericordia, y que se duele del castigo.'),
  VersiculoDiario(51, 2, 10, 10, TemaVersiculo.identidad, 'Y vosotros estáis completos en él, que es la cabeza de todo principado y potestad.'),
  VersiculoDiario(19, 5, 11, 11, TemaVersiculo.gozo, 'Pero alégrense todos los que en ti confían; Den voces de júbilo para siempre, porque tú los defiendes; En ti se regocijen los que aman tu nombre.'),
  VersiculoDiario(45, 6, 12, 12, TemaVersiculo.tentacion, 'No reine, pues, el pecado en vuestro cuerpo mortal, de modo que lo obedezcáis en sus concupiscencias;'),
  VersiculoDiario(19, 18, 29, 29, TemaVersiculo.victoria, 'Contigo desbarataré ejércitos, Y con mi Dios asaltaré muros.'),
  VersiculoDiario(47, 4, 16, 16, TemaVersiculo.fortaleza, 'Por tanto, no desmayamos; antes aunque este nuestro hombre exterior se va desgastando, el interior no obstante se renueva de día en día.'),
  VersiculoDiario(50, 1, 6, 6, TemaVersiculo.esperanza, 'Estando persuadido de esto, que el que comenzó en vosotros la buena obra, la perfeccionará hasta el día de Jesucristo;'),
  VersiculoDiario(20, 30, 5, 5, TemaVersiculo.palabra, 'Toda palabra de Dios es limpia; Él es escudo a los que en él esperan.'),
  VersiculoDiario(43, 1, 17, 17, TemaVersiculo.gracia, 'Pues la ley por medio de Moisés fue dada, pero la gracia y la verdad vinieron por medio de Jesucristo.'),
  VersiculoDiario(19, 139, 23, 24, TemaVersiculo.pureza, 'Examíname, oh Dios, y conoce mi corazón; Pruébame y conoce mis pensamientos; Y ve si hay en mí camino de perversidad, Y guíame en el camino eterno.'),
  VersiculoDiario(19, 116, 7, 7, TemaVersiculo.paz, 'Vuelve, oh alma mía, a tu reposo, Porque Jehová te ha hecho bien.'),
  VersiculoDiario(42, 12, 7, 7, TemaVersiculo.amor, 'Pues aun los cabellos de vuestra cabeza están todos contados. No temáis, pues; más valéis vosotros que muchos pajarillos.'),
  VersiculoDiario(19, 4, 1, 1, TemaVersiculo.oracion, 'Respóndeme cuando clamo, oh Dios de mi justicia. Cuando estaba en angustia, tú me hiciste ensanchar; Ten misericordia de mí, y oye mi oración.'),
  VersiculoDiario(41, 11, 22, 22, TemaVersiculo.fe, 'Respondiendo Jesús, les dijo: Tened fe en Dios.'),
  VersiculoDiario(46, 16, 13, 13, TemaVersiculo.fortaleza, 'Velad, estad firmes en la fe; portaos varonilmente, y esforzaos.'),
  VersiculoDiario(42, 15, 7, 7, TemaVersiculo.perdon, 'Os digo que así habrá más gozo en el cielo por un pecador que se arrepiente, que por noventa y nueve justos que no necesitan de arrepentimiento.'),
  VersiculoDiario(19, 118, 8, 8, TemaVersiculo.fe, 'Mejor es confiar en Jehová Que confiar en el hombre.'),
  VersiculoDiario(48, 5, 24, 24, TemaVersiculo.tentacion, 'Pero los que son de Cristo han crucificado la carne con sus pasiones y deseos.'),
  VersiculoDiario(19, 39, 7, 7, TemaVersiculo.esperanza, 'Y ahora, Señor, ¿qué esperaré? Mi esperanza está en ti.'),
  VersiculoDiario(19, 50, 15, 15, TemaVersiculo.oracion, 'E invócame en el día de la angustia; Te libraré, y tú me honrarás.'),
  VersiculoDiario(62, 4, 18, 18, TemaVersiculo.amor, 'En el amor no hay temor, sino que el perfecto amor echa fuera el temor; porque el temor lleva en sí castigo. De donde el que teme, no ha sido perfeccionado en el amor.'),
  VersiculoDiario(19, 32, 11, 11, TemaVersiculo.gozo, 'Alegraos en Jehová y gozaos, justos; Y cantad con júbilo todos vosotros los rectos de corazón.'),
  VersiculoDiario(19, 37, 11, 11, TemaVersiculo.paz, 'Pero los mansos heredarán la tierra, Y se recrearán con abundancia de paz.'),
  VersiculoDiario(55, 2, 1, 1, TemaVersiculo.gracia, 'Tú, pues, hijo mío, esfuérzate en la gracia que es en Cristo Jesús.'),
  VersiculoDiario(19, 119, 37, 37, TemaVersiculo.pureza, 'Aparta mis ojos, que no vean la vanidad; Avívame en tu camino.'),
  VersiculoDiario(42, 4, 18, 18, TemaVersiculo.victoria, 'El Espíritu del Señor está sobre mí, Por cuanto me ha ungido para dar buenas nuevas a los pobres; Me ha enviado a sanar a los quebrantados de corazón; A pregonar libertad a los cautivos, Y vista a los ciegos; A poner en libertad a los oprimidos;'),
  VersiculoDiario(50, 3, 20, 20, TemaVersiculo.identidad, 'Mas nuestra ciudadanía está en los cielos, de donde también esperamos al Salvador, al Señor Jesucristo;'),
  VersiculoDiario(42, 11, 28, 28, TemaVersiculo.palabra, 'Y él dijo: Antes bienaventurados los que oyen la palabra de Dios, y la guardan.'),
  VersiculoDiario(40, 6, 22, 22, TemaVersiculo.pureza, 'La lámpara del cuerpo es el ojo; así que, si tu ojo es bueno, todo tu cuerpo estará lleno de luz;'),
  VersiculoDiario(53, 3, 3, 3, TemaVersiculo.fortaleza, 'Pero fiel es el Señor, que os afirmará y guardará del mal.'),
  VersiculoDiario(19, 62, 1, 1, TemaVersiculo.paz, 'En Dios solamente está acallada mi alma; De él viene mi salvación.'),
  VersiculoDiario(19, 107, 14, 14, TemaVersiculo.victoria, 'Los sacó de las tinieblas y de la sombra de muerte, Y rompió sus prisiones.'),
  VersiculoDiario(46, 6, 11, 11, TemaVersiculo.identidad, 'Y esto erais algunos; mas ya habéis sido lavados, ya habéis sido santificados, ya habéis sido justificados en el nombre del Señor Jesús, y por el Espíritu de nuestro Dios.'),
  VersiculoDiario(19, 103, 10, 10, TemaVersiculo.perdon, 'No ha hecho con nosotros conforme a nuestras iniquidades, Ni nos ha pagado conforme a nuestros pecados.'),
  VersiculoDiario(45, 8, 32, 32, TemaVersiculo.amor, 'El que no escatimó ni a su propio Hijo, sino que lo entregó por todos nosotros, ¿cómo no nos dará también con él todas las cosas?'),
  VersiculoDiario(43, 14, 1, 1, TemaVersiculo.fe, 'No se turbe vuestro corazón; creéis en Dios, creed también en mí.'),
  VersiculoDiario(60, 2, 2, 2, TemaVersiculo.palabra, 'Desead, como niños recién nacidos, la leche espiritual no adulterada, para que por ella crezcáis para salvación,'),
  VersiculoDiario(51, 3, 2, 2, TemaVersiculo.tentacion, 'Poned la mira en las cosas de arriba, no en las de la tierra.'),
  VersiculoDiario(24, 17, 7, 7, TemaVersiculo.esperanza, 'Bendito el varón que confía en Jehová, y cuya confianza es Jehová.'),
  VersiculoDiario(45, 6, 23, 23, TemaVersiculo.gracia, 'Porque la paga del pecado es muerte, mas la dádiva de Dios es vida eterna en Cristo Jesús Señor nuestro.'),
  VersiculoDiario(19, 40, 3, 3, TemaVersiculo.gozo, 'Puso luego en mi boca cántico nuevo, alabanza a nuestro Dios. Verán esto muchos, y temerán, Y confiarán en Jehová.'),
  VersiculoDiario(40, 18, 20, 20, TemaVersiculo.oracion, 'Porque donde están dos o tres congregados en mi nombre, allí estoy yo en medio de ellos.'),
  VersiculoDiario(40, 18, 21, 22, TemaVersiculo.perdon, 'Entonces se le acercó Pedro y le dijo: Señor, ¿cuántas veces perdonaré a mi hermano que peque contra mí? ¿Hasta siete? Jesús le dijo: No te digo hasta siete, sino aun hasta setenta veces siete.'),
  VersiculoDiario(51, 3, 5, 5, TemaVersiculo.pureza, 'Haced morir, pues, lo terrenal en vosotros: fornicación, impureza, pasiones desordenadas, malos deseos y avaricia, que es idolatría;'),
  VersiculoDiario(49, 6, 17, 17, TemaVersiculo.palabra, 'Y tomad el yelmo de la salvación, y la espada del Espíritu, que es la palabra de Dios;'),
  VersiculoDiario(19, 71, 14, 14, TemaVersiculo.esperanza, 'Mas yo esperaré siempre, Y te alabaré más y más.'),
  VersiculoDiario(19, 141, 2, 2, TemaVersiculo.oracion, 'Suba mi oración delante de ti como el incienso, El don de mis manos como la ofrenda de la tarde.'),
  VersiculoDiario(23, 41, 13, 13, TemaVersiculo.fortaleza, 'Porque yo Jehová soy tu Dios, quien te sostiene de tu mano derecha, y te dice: No temas, yo te ayudo.'),
  VersiculoDiario(20, 27, 12, 12, TemaVersiculo.tentacion, 'El avisado ve el mal y se esconde; Mas los simples pasan y llevan el daño.'),
  VersiculoDiario(55, 4, 18, 18, TemaVersiculo.victoria, 'Y el Señor me librará de toda obra mala, y me preservará para su reino celestial. A él sea gloria por los siglos de los siglos. Amén.'),
  VersiculoDiario(47, 5, 21, 21, TemaVersiculo.identidad, 'Al que no conoció pecado, por nosotros lo hizo pecado, para que nosotros fuésemos hechos justicia de Dios en él.'),
  VersiculoDiario(42, 1, 37, 37, TemaVersiculo.fe, 'Porque nada hay imposible para Dios.'),
  VersiculoDiario(42, 2, 14, 14, TemaVersiculo.paz, '¡Gloria a Dios en las alturas, Y en la tierra paz, buena voluntad para con los hombres!'),
  VersiculoDiario(43, 16, 27, 27, TemaVersiculo.amor, 'Pues el Padre mismo os ama, porque vosotros me habéis amado, y habéis creído que yo salí de Dios.'),
  VersiculoDiario(23, 12, 3, 3, TemaVersiculo.gozo, 'Sacaréis con gozo aguas de las fuentes de la salvación.'),
  VersiculoDiario(45, 10, 13, 13, TemaVersiculo.gracia, 'Porque todo aquel que invocare el nombre del Señor, será salvo.'),
  VersiculoDiario(58, 10, 23, 23, TemaVersiculo.esperanza, 'Mantengamos firme, sin fluctuar, la profesión de nuestra esperanza, porque fiel es el que prometió.'),
  VersiculoDiario(19, 23, 6, 6, TemaVersiculo.amor, 'Ciertamente el bien y la misericordia me seguirán todos los días de mi vida, Y en la casa de Jehová moraré por largos días.'),
  VersiculoDiario(19, 34, 14, 14, TemaVersiculo.paz, 'Apártate del mal, y haz el bien; Busca la paz, y síguela.'),
  VersiculoDiario(43, 1, 1, 1, TemaVersiculo.palabra, 'En el principio era el Verbo, y el Verbo era con Dios, y el Verbo era Dios.'),
  VersiculoDiario(19, 51, 7, 7, TemaVersiculo.pureza, 'Purifícame con hisopo, y seré limpio; Lávame, y seré más blanco que la nieve.'),
  VersiculoDiario(42, 11, 13, 13, TemaVersiculo.oracion, 'Pues si vosotros, siendo malos, sabéis dar buenas dádivas a vuestros hijos, ¿cuánto más vuestro Padre celestial dará el Espíritu Santo a los que se lo pidan?'),
  VersiculoDiario(65, 1, 24, 25, TemaVersiculo.victoria, 'Y a aquel que es poderoso para guardaros sin caída, y presentaros sin mancha delante de su gloria con gran alegría, al único y sabio Dios, nuestro Salvador, sea gloria y majestad, imperio y potencia, ahora y por todos los siglos. Amén.'),
  VersiculoDiario(49, 2, 19, 19, TemaVersiculo.identidad, 'Así que ya no sois extranjeros ni advenedizos, sino conciudadanos de los santos, y miembros de la familia de Dios,'),
  VersiculoDiario(43, 3, 17, 17, TemaVersiculo.gracia, 'Porque no envió Dios a su Hijo al mundo para condenar al mundo, sino para que el mundo sea salvo por él.'),
  VersiculoDiario(19, 141, 4, 4, TemaVersiculo.tentacion, 'No dejes que se incline mi corazón a cosa mala, A hacer obras impías Con los que hacen iniquidad; Y no coma yo de sus deleites.'),
  VersiculoDiario(41, 11, 25, 25, TemaVersiculo.perdon, 'Y cuando estéis orando, perdonad, si tenéis algo contra alguno, para que también vuestro Padre que está en los cielos os perdone a vosotros vuestras ofensas.'),
  VersiculoDiario(19, 51, 12, 12, TemaVersiculo.gozo, 'Vuélveme el gozo de tu salvación, Y espíritu noble me sustente.'),
  VersiculoDiario(19, 55, 22, 22, TemaVersiculo.fortaleza, 'Echa sobre Jehová tu carga, y él te sustentará; No dejará para siempre caído al justo.'),
  VersiculoDiario(43, 20, 29, 29, TemaVersiculo.fe, 'Jesús le dijo: Porque me has visto, Tomás, creíste; bienaventurados los que no vieron, y creyeron.'),
  VersiculoDiario(23, 26, 12, 12, TemaVersiculo.paz, 'Jehová, tú nos darás paz, porque también hiciste en nosotros todas nuestras obras.'),
  VersiculoDiario(19, 37, 23, 24, TemaVersiculo.fortaleza, 'Por Jehová son ordenados los pasos del hombre, Y él aprueba su camino. Cuando el hombre cayere, no quedará postrado, Porque Jehová sostiene su mano.'),
  VersiculoDiario(19, 84, 11, 11, TemaVersiculo.gracia, 'Porque sol y escudo es Jehová Dios; Gracia y gloria dará Jehová. No quitará el bien a los que andan en integridad.'),
  VersiculoDiario(23, 40, 11, 11, TemaVersiculo.amor, 'Como pastor apacentará su rebaño; en su brazo llevará los corderos, y en su seno los llevará; pastoreará suavemente a las recién paridas.'),
  VersiculoDiario(34, 1, 7, 7, TemaVersiculo.fe, 'Jehová es bueno, fortaleza en el día de la angustia; y conoce a los que en él confían.'),
  VersiculoDiario(62, 2, 1, 1, TemaVersiculo.perdon, 'Hijitos míos, estas cosas os escribo para que no pequéis; y si alguno hubiere pecado, abogado tenemos para con el Padre, a Jesucristo el justo.'),
  VersiculoDiario(55, 2, 21, 21, TemaVersiculo.pureza, 'Así que, si alguno se limpia de estas cosas, será instrumento para honra, santificado, útil al Señor, y dispuesto para toda buena obra.'),
  VersiculoDiario(51, 3, 12, 12, TemaVersiculo.identidad, 'Vestíos, pues, como escogidos de Dios, santos y amados, de entrañable misericordia, de benignidad, de humildad, de mansedumbre, de paciencia;'),
  VersiculoDiario(59, 1, 5, 5, TemaVersiculo.oracion, 'Y si alguno de vosotros tiene falta de sabiduría, pídala a Dios, el cual da a todos abundantemente y sin reproche, y le será dada.'),
  VersiculoDiario(19, 146, 2, 2, TemaVersiculo.gozo, 'Alabaré a Jehová en mi vida; Cantaré salmos a mi Dios mientras viva.'),
  VersiculoDiario(52, 5, 22, 22, TemaVersiculo.tentacion, 'Absteneos de toda especie de mal.'),
  VersiculoDiario(19, 119, 18, 18, TemaVersiculo.palabra, 'Abre mis ojos, y miraré Las maravillas de tu ley.'),
  VersiculoDiario(46, 15, 58, 58, TemaVersiculo.victoria, 'Así que, hermanos míos amados, estad firmes y constantes, creciendo en la obra del Señor siempre, sabiendo que vuestro trabajo en el Señor no es en vano.'),
  VersiculoDiario(19, 40, 1, 2, TemaVersiculo.esperanza, 'Pacientemente esperé a Jehová, Y se inclinó a mí, y oyó mi clamor. Y me hizo sacar del pozo de la desesperación, del lodo cenagoso; Puso mis pies sobre peña, y enderezó mis pasos.'),
  VersiculoDiario(19, 17, 6, 6, TemaVersiculo.oracion, 'Yo te he invocado, por cuanto tú me oirás, oh Dios; Inclina a mí tu oído, escucha mi palabra.'),
  VersiculoDiario(54, 4, 12, 12, TemaVersiculo.pureza, 'Ninguno tenga en poco tu juventud, sino sé ejemplo de los creyentes en palabra, conducta, amor, espíritu, fe y pureza.'),
  VersiculoDiario(60, 1, 8, 8, TemaVersiculo.gozo, 'A quien amáis sin haberle visto, en quien creyendo, aunque ahora no lo veáis, os alegráis con gozo inefable y glorioso;'),
  VersiculoDiario(45, 8, 6, 6, TemaVersiculo.tentacion, 'Porque el ocuparse de la carne es muerte, pero el ocuparse del Espíritu es vida y paz.'),
  VersiculoDiario(23, 30, 18, 18, TemaVersiculo.gracia, 'Por tanto, Jehová esperará para tener piedad de vosotros, y por tanto, será exaltado teniendo de vosotros misericordia; porque Jehová es Dios justo; bienaventurados todos los que confían en él.'),
  VersiculoDiario(23, 44, 22, 22, TemaVersiculo.perdon, 'Yo deshice como una nube tus rebeliones, y como niebla tus pecados; vuélvete a mí, porque yo te redimí.'),
  VersiculoDiario(42, 15, 4, 4, TemaVersiculo.amor, '¿Qué hombre de vosotros, teniendo cien ovejas, si pierde una de ellas, no deja las noventa y nueve en el desierto, y va tras la que se perdió, hasta encontrarla?'),
  VersiculoDiario(24, 15, 16, 16, TemaVersiculo.palabra, 'Fueron halladas tus palabras, y yo las comí; y tu palabra me fue por gozo y por alegría de mi corazón; porque tu nombre se invocó sobre mí, oh Jehová Dios de los ejércitos.'),
  VersiculoDiario(19, 34, 19, 19, TemaVersiculo.victoria, 'Muchas son las aflicciones del justo, Pero de todas ellas le librará Jehová.'),
  VersiculoDiario(48, 6, 9, 9, TemaVersiculo.fortaleza, 'No nos cansemos, pues, de hacer bien; porque a su tiempo segaremos, si no desmayamos.'),
  VersiculoDiario(60, 2, 10, 10, TemaVersiculo.identidad, 'Vosotros que en otro tiempo no erais pueblo, pero que ahora sois pueblo de Dios; que en otro tiempo no habíais alcanzado misericordia, pero ahora habéis alcanzado misericordia.'),
  VersiculoDiario(19, 94, 19, 19, TemaVersiculo.paz, 'En la multitud de mis pensamientos dentro de mí, Tus consolaciones alegraban mi alma.'),
  VersiculoDiario(19, 27, 14, 14, TemaVersiculo.esperanza, 'Aguarda a Jehová; Esfuérzate, y aliéntese tu corazón; Sí, espera a Jehová.'),
  VersiculoDiario(19, 34, 8, 8, TemaVersiculo.fe, 'Gustad, y ved que es bueno Jehová; Dichoso el hombre que confía en él.'),
];
